**Brief Plan**

To implement a thread-safe unbounded queue using pthreads:

1. **Data Structure**: Use a linked list with a dummy node to separate head and tail operations, enabling efficient concurrent enqueue and dequeue.
2. **Synchronization**:
   - Use a mutex for the head of the queue (to protect head operations).
   - Use a mutex for the tail of the queue (to protect tail operations).
   - Use condition variables:
     - `cv_empty` to wait when the queue is empty (for dequeue).
     - `cv_full` to wait when the queue is full (for enqueue). Since it's unbounded, we don’t need a full condition.
3. **Operations**:
   - `enqueue`: Acquires tail lock, adds node, signals one waiting dequeuer (if any).
   - `dequeue`: Acquires head lock, removes node, signals one waiting enqueuer (if any).
4. **Initialization**: Dummy node is used to avoid special cases when the queue is empty.
5. **Test Driver**: Two threads: one enqueues integers (1 to 10), another dequeues and prints them.

This design ensures:
- **Mutual exclusion** in critical sections (head and tail operations).
- **Progress**: Threads do not block indefinitely (condition variables are used with proper wait/signal).
- **No deadlock**: Each thread only waits on a condition that will eventually be signaled (no circular waits).
- **No lost wakeups**: Only one thread is signaled per `signal()` call, and the condition is checked in a loop.

---

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

// Node structure
typedef struct node {
    int value;
    struct node *next;
} node_t;

// Queue structure with head and tail locks
typedef struct {
    node_t *head;
    node_t *tail;
    pthread_mutex_t head_lock;
    pthread_mutex_t tail_lock;
    pthread_cond_t cv_empty;  // Wait if queue is empty
    pthread_cond_t cv_full;   // Wait if queue is full (unbounded, so not used)
} queue_t;

queue_t *q;

// Initialize the queue with dummy node
void queue_init() {
    q = malloc(sizeof(queue_t));
    if (!q) {
        perror("malloc failed");
        exit(1);
    }

    q->head = malloc(sizeof(node_t));
    q->tail = q->head;
    q->head->next = NULL;

    pthread_mutex_init(&q->head_lock, NULL);
    pthread_mutex_init(&q->tail_lock, NULL);
    pthread_cond_init(&q->cv_empty, NULL);
    pthread_cond_init(&q->cv_full, NULL);
}

// Enqueue operation
void enqueue(int value) {
    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        perror("malloc failed");
        return;
    }
    new_node->value = value;
    new_node->next = NULL;

    pthread_mutex_lock(&q->tail_lock);
    q->tail->next = new_node;
    q->tail = new_node;
    pthread_mutex_unlock(&q->tail_lock);

    // Signal one waiting dequeuer (if any)
    pthread_cond_signal(&q->cv_empty);
}

// Dequeue operation
int dequeue() {
    int value = -1;
    node_t *node;

    pthread_mutex_lock(&q->head_lock);
    if (q->head->next == NULL) {
        // Queue is empty — wait until something is added
        printf("Dequeue: queue empty, waiting...\n");
        pthread_cond_wait(&q->cv_empty, &q->head_lock);
    }
    node = q->head->next;
    q->head->next = node->next;
    pthread_mutex_unlock(&q->head_lock);

    value = node->value;
    free(node);

    // Signal one waiting enqueuer (if any)
    pthread_cond_signal(&q->cv_full);

    return value;
}

// Thread function for producer (enqueue)
void *producer(void *arg) {
    for (int i = 1; i <= 10; i++) {
        enqueue(i);
        printf("Producer enqueued: %d\n", i);
        usleep(10000); // Small delay to simulate work
    }
    return NULL;
}

// Thread function for consumer (dequeue)
void *consumer(void *arg) {
    for (int i = 0; i < 10; i++) {
        int val = dequeue();
        if (val == -1) {
            printf("Consumer: dequeue failed\n");
            break;
        }
        printf("Consumer dequeued: %d\n", val);
    }
    return NULL;
}

// Test driver
int main() {
    printf("Initializing queue...\n");
    queue_init();

    pthread_t prod, cons;
    printf("Creating producer and consumer threads...\n");

    pthread_create(&prod, NULL, producer, NULL);
    pthread_create(&cons, NULL, consumer, NULL);

    pthread_join(prod, NULL);
    pthread_join(cons, NULL);

    printf("All operations complete.\n");
    return 0;
}
```

