    waitingCount++;
    printf("Customer %d sits in waiting room.\n", id);
    pthread_cond_signal(&barberWoken);
    pthread_mutex_unlock(&mutex);

    // Wait for barber to serve
    pthread_mutex_lock(&mutex);
    while (waitingCount > 0) {
        printf("Customer %d is waiting for haircut.\n", id);
        pthread_cond_wait(&barberWoken, &mutex);
    }
    pthread_mutex_unlock(&mutex);

    printf("Customer %d has finished getting haircut.\n", id);
    return NULL;
}

