#include <unistd.h>

#define K 3  // Maximum number of cars that can park at once

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int parked_count = 0;
int num_cars = 0;
int max_cars = K;

void* car_thread(void *arg) {
    int id = *(int*)arg;
    srand(time(NULL) + id);  // Seed for randomness

    // Try to park
    pthread_mutex_lock(&lock);
    while (parked_count >= max_cars) {
        printf("Car %d: No space available, waiting...\n", id);
        pthread_cond_wait(&cond, &lock);
    }
    parked_count++;
    printf("Car %d: Parked in space %d\n", id, parked_count);
    pthread_mutex_unlock(&lock);

    // Simulate parking duration (random between 100ms and 500ms)
    usleep(rand() % 400000 + 100000);  // 100ms to 500ms

    // Leave
    pthread_mutex_lock(&lock);
    parked_count--;
    printf("Car %d: Left, space now free\n", id);
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);

    return NULL;
}

