    // Thread A waits for B to arrive
    sem_wait(&bArrived);
    printf("Thread A: rendezvous complete, proceeding\n");
    return NULL;
}

void* thread_b(void* arg) {
    printf("Thread B: arriving at rendezvous\n");
    // Thread B waits for A to arrive
    sem_wait(&aArrived);
    printf("Thread B: rendezvous complete, proceeding\n");
