```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

// Shared semaphores for rendezvous
sem_t semA, semB;

// Global iteration counter
int iteration = 0;

// Thread function for A
void* threadA(void* arg) {
    for (int i = 0; i < 5; i++) {
        printf("Thread A: waiting for Thread B at iteration %d\n", i);
        sem_wait(&semB);  // Wait for B to arrive
        printf("Thread A: proceeding after rendezvous at iteration %d\n", i);
        sem_post(&semA);  // Signal B to proceed
    }
    return NULL;
}

// Thread function for B
void* threadB(void* arg) {
    for (int i = 0; i < 5; i++) {
        printf("Thread B: waiting for Thread A at iteration %d\n", i);
        sem_wait(&semA);  // Wait for A to arrive
        printf("Thread B: proceeding after rendezvous at iteration %d\n", i);
        sem_post(&semB);  // Signal A to proceed
    }
    return NULL;
}

int main() {
    // Initialize semaphores to 0
    sem_init(&semA, 0, 0);
    sem_init(&semB, 0, 0);

    // Create two threads
    pthread_t threadA_id, threadB_id;
    pthread_create(&threadA_id, NULL, threadA, NULL);
    pthread_create(&threadB_id, NULL, threadB, NULL);

    // Wait for both threads to finish
    pthread_join(threadA_id, NULL);
    pthread_join(threadB_id, NULL);

    // Clean up semaphores
    sem_destroy(&semA);
    sem_destroy(&semB);

    printf("Both threads completed 5 iterations successfully.\n");
    return 0;
