-        pthread_mutex_lock(&arm_mutex);
-        if (arm_load_capacity < 80) {
-            pthread_cond_wait(&arm_cond, &arm_mutex);
-        }
-        assert(arm_load_capacity >= 80);
-        arm_load_capacity -= 30;
-        pthread_mutex_unlock(&arm_mutex);
+        pthread_mutex_lock(&arm_mutex);
+        while (arm_load_capacity < 80) {
